        },
        {
          "@type": "HowToStep",
          "position": 2,
          "name": "Schedule Pickup",
          "text": "Coordinate a pickup plan for the Bakersfield location based on equipment volume, access requirements, operating schedules, and project timing."
        },
        {
          "@type": "HowToStep",
          "position": 3,
          "name": "Arrange Secure Transport",
          "text": "Equipment is coordinated for transport from Bakersfield with documented chain-of-custody procedures and project records."
        },
        {
          "@type": "HowToStep",
          "position": 4,
          "name": "Track Equipment and Handle Data",
          "text": "STS coordinates equipment records, data sanitization or destruction methods, serial-level tracking, and documentation based on the project scope."
        },
        {
          "@type": "HowToStep",
          "position": 5,
          "name": "Process Materials",
          "text": "Equipment is sorted for documented downstream material recovery, reuse opportunities, and appropriate electronic recycling procedures."
        },
        {
          "@type": "HowToStep",
          "position": 6,
          "name": "Receive Project Documentation",
          "text": "Organizations can request applicable equipment records, certificates, destruction methods, and downstream reporting for their internal review.",
