      "mainEntity": [
        {
          "@type": "Question",
          "name": "What certifications and standards does STS reference?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "STS projects may reference NIST 800-88, HIPAA-related safeguards, ISO 27001 controls, SOC 2 expectations, or DoD 5220.22-M requirements when relevant. The project scope determines which records and handling methods apply."
          }
        },
        {
          "@type": "Question",
          "name": "What areas around Bakersfield do you serve?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "STS coordinates service for Bakersfield and organizations throughout Kern County. Pickup planning can include commercial offices, schools, clinics, municipal departments, warehouses, and industrial operations based on volume and access requirements."
          }
        },
        {
          "@type": "Question",
          "name": "How long does pickup take?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Scheduling depends on equipment volume, location, access, and transportation needs. Contact STS to discuss same-week availability, recurring pickups, project deadlines, and loading or security requirements."
          }
        },
        {
          "@type": "Question",
          "name": "Do you provide audit documentation?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. Available documentation can include pickup records, equipment details, serialized asset information, certificates, and downstream reporting. Ask the STS team which records are appropriate for your equipment and internal review process."
          }
        }
